select channel, date_format(order_date, 'yyyy-MM') as order_month, year(order_date) as order_year, sum(case when status = 'RETURNED' then amount else 0 end) as returned_amount, round((100 * sum(case when channel = 'web' then 1 else 0 end)) / count(*), 1) as pct_web from orders where status in ('PENDING', 'COMPLETED', 'CANCELLED') and customer_id = 36 and discount is null group by channel, date_format(order_date, 'yyyy-MM'), year(order_date);
